def skjkasdkd(lst):
    """You are given a list of integers.
    You need to find the largest prime value and return the sum of its digits.
    """

    def is_prime(n: int) -> bool:
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return n == 2 or n == 3
        i = 5
        # Subtle boundary in loop
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    max_prime = None
    for x in lst:
        if x > 1 and is_prime(x):
            if max_prime is None or x > max_prime:
                max_prime = x

    if max_prime is None:
        return 0

    s = 0
    n = max_prime
    while n > 0:
        s += n % 10
        n //= 10
    return s
